app "My Age" user pink
setting born date = today "Date of birth"
let yrs = year(today) - year(born) - if(month(today) * 100 + monthday(today) < month(born) * 100 + monthday(born), 1, 0)
let mon_since = addmonths(born, yrs * 12)
let mths = year(today) * 12 + month(today) - year(mon_since) * 12 - month(mon_since) - if(monthday(today) < monthday(mon_since), 1, 0)
let dys = today - addmonths(mon_since, mths)
let nextb = addmonths(born, (yrs + 1) * 12)
field born
if born >= today
  "Pick a birth date in the past to see your age." faint
else
  statcard yrs, "years," mths "months and" dys "days old", 0
  section "More about you"
    "Days lived" today - born big
    "Born on a" dayname(born) faint
    "Next birthday" nextb "in" plural(nextb - today, "day") head

