app "Percent from Marks" school pink
let ceil0(x num) = floor(x) + if(x > floor(x), 1, 0)
state got num = 0
state out num = 100
let pct = if(out > 0, got * 100 / out, 0)
let grade = if(pct >= 80, "A+", if(pct >= 70, "A", if(pct >= 60, "B", if(pct >= 50, "C", if(pct >= 40, "D", "F")))))
let nextcut = if(pct >= 80, 80, if(pct >= 70, 80, if(pct >= 60, 70, if(pct >= 50, 60, if(pct >= 40, 50, 40)))))
field got "Marks obtained"
field out "Total marks"
statcard round(pct * 10) / 10, "percent", 100
"Grade" grade big
if pct < 80
  "Next grade at" nextcut "%, which is" ceil0(nextcut * out / 100 - got) "more marks." faint

